    slug: "open-source-silicon-roots-trust",
    title: { zh: "开源硅信任根", en: "Open-Source Silicon Roots of Trust" },
    qfocus: { zh: "公开的 RTL 与出厂的那颗硅片是否一致——在流片、掩膜与封装仍闭源时，这一等价性能被独立证明吗？", en: "Does the shipped die match the published RTL — and while tapeout, masks and packaging stay closed, can that equivalence be proven independently?" },
    domain: "物质",
    cluster: { code: "C47", zh: "后量子·隐私计算工程", en: "Post-quantum · privacy-preserving computation" },
    scores: [4, 4, 4, 3, 4, 1, 5, 2, 4],
    citation: {
      url: "https://dl.acm.org/doi/10.1145/3690823",
      title: "Unleashing OpenTitan's Potential: a Silicon-Ready Embedded Secure Element for Root of Trust and Cryptographic Offloading",
      venue: "ACM Transactions on Embedded Computing Systems",
      year: 2024,
    },
    brief: { zh: "把 RTL、固件与规范全部公开，对开源信任根做侧信道与故障注入加固，并发展硅—RTL 等价性验证：以去封装成像、旁路特征比对与可复现构建记录检验出厂芯片是否就是公开设计。", en: "Publish RTL, firmware and specifications in full, harden the open root of trust against side channels and fault injection, and develop silicon-to-RTL equivalence verification — decapsulation imaging, side-channel signature comparison and reproducible build records that test whether the shipped part is the published design." },
    literature: [
      { title: "OpenTitan shipping in production", venue: "Google Open Source Blog", year: 2026, url: "https://opensource.googleblog.com/2026/03/opentitan-shipping-in-production.html" },
      { title: "Caliptra 2.1: An Open-Source Silicon Root of Trust With Enhanced Protection of Data At-Rest", venue: "Microsoft Azure Infrastructure Blog", year: 2025, url: "https://techcommunity.microsoft.com/blog/azureinfrastructureblog/caliptra-2-1-an-open-source-silicon-root-of-trust-with-enhanced-protection-of-da/4460758" },
      { title: "OpenTitan Partnership Makes History as First Open-Source Silicon Project to Reach Commercial Availability", venue: "lowRISC", year: 2024, url: "https://lowrisc.org/news/opentitan-commercial-availability/" },
    ],
    depth: {
      overview: { zh: "你可以审计操作系统与编译器，但机密计算最底层那颗决定“证明报告可不可信”的芯片一直是黑盒。OpenTitan 2023 年首次流片，2024 年成为史上首个达到商用可用性的开源硅项目，2026 年进入量产设备；OCP 的 Caliptra 已迭代到 2.1，整合 OpenTitan 组件并直接嵌入 CPU、GPU 与 SSD。", en: "You can audit the operating system and the compiler, but the chip at the bottom of confidential computing — the one that decides whether an attestation report can be believed — has always been a black box. OpenTitan taped out in 2023, became in 2024 the first open-source silicon project to reach commercial availability, and by 2026 shipped in production devices; OCP's Caliptra has reached 2.1, integrating OpenTitan components directly into CPUs, GPUs and SSDs." },
      whyMatters: { zh: "“信任硬件厂商”是机密计算里唯一无法审计的公理，整条证明链最终锚在它上面；但开源 RTL 不等于开源芯片，流片、掩膜与封装仍握在闭源供应链手里。", en: "“Trust the hardware vendor” is the one unauditable axiom in confidential computing, and the whole attestation chain is anchored to it. Yet open RTL is not an open chip: tapeout, masks and packaging remain in the hands of a closed supply chain." },
      ifAnswered: { zh: "可审计的信任锚会从差异化卖点变成机密计算采购的合规基线，证明链的每一层都能被独立复核。", en: "An auditable trust anchor would move from a differentiator to a compliance baseline for confidential-computing procurement, and every layer of the attestation chain could be independently rechecked." },
      approaches: [
        { zh: "公开 RTL、固件与规范，让信任锚可被独立审计，并以硅级就绪度评估佐证其可用性。", en: "Publish RTL, firmware and specifications so the trust anchor can be audited independently, backed by silicon-readiness evaluation of the secure element." },
        { zh: "发展硅—RTL 等价性验证：去封装成像、旁路特征比对与可复现的流片构建记录。", en: "Develop silicon-to-RTL equivalence verification through decapsulation imaging, side-channel signature comparison and reproducible tapeout build records." },
        { zh: "对开源信任根做侧信道与故障注入加固，并推动多厂商证明格式与策略互操作。", en: "Harden the open root of trust against side-channel and fault-injection attacks, and drive interoperability of attestation formats and policies across vendors." },
      ],
      barrier: { zh: "开源 RTL 不等于开源芯片：流片、掩膜与封装仍在闭源供应链手中，如何证明出厂硅片与公开 RTL 一致，几乎是一片空白的研究领域。", en: "Open-source RTL is not an open-source chip: tapeout, masks and packaging remain inside a closed supply chain, and proving that the shipped die matches the published RTL is very nearly a blank research area." },
      subQuestions: [
        { zh: "去封装成像与旁路特征能把硅—RTL 等价性验证到哪一层级，代价与破坏性各是多少？", en: "To what level can decapsulation imaging and side-channel signatures verify silicon-to-RTL equivalence, and at what cost and destructiveness?" },
        { zh: "开源设计公开了实现细节，会不会同时降低侧信道攻击门槛，加固能否在不闭源前提下有效？", en: "Does publishing implementation detail also lower the bar for side-channel attacks, and can hardening remain effective without closing the design?" },
        { zh: "多厂商信任根并存时，证明格式与信任策略如何互操作而不退回单一供应商依赖？", en: "When roots of trust from several vendors coexist, how can attestation formats and trust policies interoperate without falling back into single-vendor dependence?" },
      ],
    },
